using EEMS.Modules.Identity.Infrastructure;using EEMS.Modules.Reporting.Infrastructure;using EEMS.SharedKernel.Tenancy;using Microsoft.EntityFrameworkCore;
namespace EEMS.Api.Audit;
public sealed class AuditNotificationService(ReportingDbContext db,IdentityDbContext identity,ITenantContext tenant){public async Task<AuditPage> GetAudit(string? search,int page,int pageSize,CancellationToken ct){var query=db.AuditLogs.Where(x=>x.TenantId==tenant.TenantId);if(!string.IsNullOrWhiteSpace(search)){var term=$"%{search.Trim()}%";query=query.Where(x=>EF.Functions.ILike(x.Action,term)||EF.Functions.ILike(x.EntityType,term)||EF.Functions.ILike(x.EntityId,term)||EF.Functions.ILike(x.CorrelationId,term));}var count=await query.CountAsync(ct);var rows=await query.OrderByDescending(x=>x.OccurredAtUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);var users=await identity.Users.Where(x=>rows.Select(r=>r.ActorUserId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.DisplayName,ct);return new(rows.Select(x=>new AuditEntry(x.Id,x.ActorUserId,users.GetValueOrDefault(x.ActorUserId,"Unknown user"),x.Action,x.EntityType,x.EntityId,x.CorrelationId,x.MetadataJson,x.OccurredAtUtc)).ToArray(),count,page,pageSize);}
public async Task<NotificationFeed> GetNotifications(CancellationToken ct){var security=await db.SecurityEvents.Where(x=>x.TenantId==tenant.TenantId).OrderByDescending(x=>x.OccurredAtUtc).Take(30).Select(x=>new NotificationItem(x.Id.ToString(),"security",x.EventType,x.Detail,x.Source,x.OccurredAtUtc,true)).ToListAsync(ct);var outbox=await db.Outbox.Where(x=>x.TenantId==tenant.TenantId&&x.ProcessedAtUtc==null).OrderByDescending(x=>x.OccurredAtUtc).Take(30).Select(x=>new NotificationItem(x.Id.ToString(),"operation",x.MessageType,x.PayloadJson,x.CorrelationId,x.OccurredAtUtc,false)).ToListAsync(ct);return new(security.Concat(outbox).OrderByDescending(x=>x.OccurredAtUtc).Take(50).ToArray(),outbox.Count);}}
public sealed record AuditPage(IReadOnlyList<AuditEntry> Items,int TotalCount,int Page,int PageSize);public sealed record AuditEntry(long AuditLogId,Guid ActorUserId,string ActorName,string Action,string EntityType,string EntityId,string CorrelationId,string MetadataJson,DateTimeOffset OccurredAtUtc);public sealed record NotificationFeed(IReadOnlyList<NotificationItem> Items,int UnreadCount);public sealed record NotificationItem(string Id,string Category,string Title,string Message,string Source,DateTimeOffset OccurredAtUtc,bool IsSecurityEvent);
